        - id: mla
          type: group
          label: MLA
          color: attn
          children:
            - id: qpath
              type: leaf
              label: Q projection
              sub: split RoPE / NoPE
              color: attn
            - id: kvpath
              type: leaf
              label: KV latent cache
              sub: low-rank compression
              color: sky
            - id: sdpa
              type: leaf
              label: Attention output
              color: attn
        - id: r1
          type: leaf
          label: "+ residual"
          color: resid
        - id: ln2
          type: leaf
          label: RMSNorm
          color: norm
        - id: moe
          type: group
          label: MoE FFN
          color: moe
          children:
            - id: router
              type: leaf
              label: "Router top-{{numExpertsPerToken}}"
              sub: sigmoid + correction bias
              color: teal
            - id: experts
              type: row
              children:
                - id: routed
                  type: leaf
                  label: Routed experts
                  color: moe
                - id: shared
                  type: leaf
                  label: "Shared x{{numSharedExperts}}"
                  color: amber
        - id: r2
          type: leaf
          label: "+ residual"
          color: resid
    - id: head
      type: leaf
      label: LM Head
      color: out
');
